insert into _recomendaciones (lista, codigo, nombre, grupo, orden, categoria, texto) values
  ('recomendacion_aptitud', 'apto', null, 'PER,ANU', null, null, E'Puede desempeñar las funciones del cargo evaluado sin limitaciones médicas al momento de la evaluación.\nCumplir las normas de seguridad del puesto y usar en todo momento el equipo de protección personal asignado.\nAcudir al servicio médico ante cualquier síntoma, molestia o lesión relacionada con su trabajo, sin esperar a la próxima evaluación.\nAsistir a la evaluación médica periódica en la fecha indicada según los riesgos de su puesto.'),
  ('recomendacion_aptitud', 'preempleo', null, null, null, null, E'Apto para iniciar labores en el cargo evaluado.\nAntes del primer día de trabajo debe recibir la inducción en seguridad y salud en el trabajo y la notificación escrita de los riesgos del puesto (LOPCYMAT art. 53 y 56).\nUsar desde el inicio el equipo de protección personal asignado y cumplir los procedimientos de trabajo seguro.\nInformar al servicio médico cualquier cambio en su estado de salud y asistir a la evaluación periódica en la fecha indicada.'),
  ('recomendacion_aptitud', 'postvacacional', null, null, null, null, E'Sin cambios en su condición de salud atribuibles al periodo vacacional: puede reincorporarse a sus labores habituales.\nRetomar las actividades usando desde el primer día el equipo de protección personal y las medidas de seguridad del puesto.\nSi presentó alguna enfermedad, lesión o tratamiento durante las vacaciones, informarlo al servicio médico y traer el soporte.\nReincorporarse de forma progresiva en tareas de mayor esfuerzo físico y avisar si aparece fatiga o molestia en los primeros días.'),
  ('recomendacion_aptitud', 'egreso', null, null, null, null, E'Se deja constancia del estado de salud del trabajador al finalizar la relación laboral.\nConservar copia de esta constancia y de los resultados de los exámenes realizados, como soporte de su condición de salud al egreso.\nSi en el futuro presenta síntomas que relacione con el trabajo realizado, puede solicitar su historia médica ocupacional al servicio médico.\nMantener sus controles médicos con su médico de confianza o en la red pública de salud.'),
  ('recomendacion_aptitud', 'pre_restriccion', null, null, null, null, E'Apto para el cargo con las restricciones indicadas en esta constancia.\nConocer sus restricciones y pedir a su supervisor que las tareas asignadas se ajusten a ellas desde el inicio de labores.\nEl trabajador debe cumplir las restricciones, no realizar tareas que las excedan y avisar al servicio médico si se le asignan.\nSe revisarán las restricciones en la próxima evaluación médica o antes, si cambia su condición de salud o el puesto de trabajo.'),
  ('recomendacion_aptitud', 'pre_espera', null, null, null, null, E'La aptitud queda en espera de los resultados de los exámenes paraclínicos y de las evaluaciones complementarias solicitadas.\nNo debe iniciar labores hasta consignar los resultados en el servicio médico y recibir la constancia de aptitud definitiva.\nRealizar los exámenes en el plazo indicado; los resultados con más de 3 meses de antigüedad pueden requerir repetirse.'),
  ('recomendacion_aptitud', 'pre_induccion', null, null, null, null, E'Antes del inicio de labores debe recibir la inducción y la notificación escrita de los riesgos del puesto (LOPCYMAT art. 53 y 56), con constancia firmada.\nConocer los procedimientos de trabajo seguro, las rutas de evacuación y el plan de respuesta a emergencias de su área.\nRecibir, aprender a usar y mantener el equipo de protección personal asignado; solicitar su reposición cuando se deteriore.'),
  ('recomendacion_aptitud', 'per_sin_cambios', null, 'PER,ANU', null, null, E'Sin cambios en su condición de salud respecto a la evaluación anterior: continúa apto para el cargo.\nMantener las medidas de prevención del puesto, el uso del equipo de protección personal y los hábitos de vida saludables.\nAcudir al servicio médico ante cualquier síntoma relacionado con el trabajo y asistir a la próxima evaluación periódica en la fecha indicada.'),
  ('recomendacion_aptitud', 'per_control', null, 'PER,ANU', null, null, E'Continúa apto para el cargo.\nRequiere control médico de los hallazgos señalados: cumplir las indicaciones, el tratamiento y las referencias a especialistas emitidas en esta consulta.\nConsignar en el servicio médico los informes y resultados de control antes de la próxima evaluación.\nSi los hallazgos progresan o aparecen síntomas nuevos, acudir al servicio médico sin esperar la fecha del control.'),
  ('recomendacion_aptitud', 'prev_apto', null, null, null, null, E'Se evalúa el estado de salud antes del periodo vacacional como referencia para la evaluación de retorno.\nDurante las vacaciones, evitar actividades de riesgo o esfuerzos físicos no habituales y mantener el descanso, la hidratación y la alimentación adecuados.\nSi presenta alguna enfermedad, lesión u hospitalización durante el periodo vacacional, guardar el informe médico y presentarlo al regreso.\nAsistir a la evaluación postvacacional antes de reincorporarse a sus labores.'),
  ('recomendacion_aptitud', 'posv_hallazgos', null, null, null, null, E'Presenta hallazgos no atribuibles a las condiciones de trabajo.\nPuede reincorporarse a sus labores con control por su médico tratante y cumpliendo el tratamiento indicado.\nConsignar en el servicio médico el informe de su médico tratante y avisar si los síntomas interfieren con sus tareas.\nEvitar automedicarse y cumplir los controles indicados hasta el alta de su médico tratante.'),
  ('recomendacion_aptitud', 'rei_apto', null, null, null, null, E'Culminado el reposo, se encuentra en condiciones de reincorporarse a sus labores habituales.\nCumplir el tratamiento y los controles indicados por su médico tratante hasta el alta definitiva.\nAcudir al servicio médico si reaparecen los síntomas o presenta dificultad para realizar sus tareas.\nEvitar automedicarse y consignar en el servicio médico todo reposo o informe médico externo.'),
  ('recomendacion_aptitud', 'rei_gradual', null, null, null, null, E'Puede reincorporarse con las limitaciones indicadas, de forma temporal y progresiva.\nRetomar las tareas de forma gradual, respetando las pausas y sin esfuerzos que excedan sus limitaciones.\nEl trabajador no debe realizar tareas que excedan las limitaciones y debe avisar si se le asignan.\nRevisión médica al vencer la vigencia de las limitaciones, o antes si cambia su condición de salud.'),
  ('recomendacion_aptitud', 'egr_sin_hallazgos', null, null, null, null, E'Al momento del egreso no se evidencian alteraciones de salud relacionadas con el trabajo.\nConservar copia de esta constancia y de los exámenes realizados como soporte de su condición de salud al egreso.\nMantener controles de salud periódicos con su médico de confianza.'),
  ('recomendacion_aptitud', 'egr_con_hallazgos', null, null, null, null, E'Al momento del egreso presenta los hallazgos descritos, de los cuales se deja constancia en su historia médica ocupacional.\nContinuar el control y tratamiento de dichos hallazgos con su médico tratante o especialista.\nConservar copia de esta constancia y de los informes médicos como soporte de su condición de salud al egreso.\nSi considera que algún hallazgo guarda relación con el trabajo realizado, puede solicitar su evaluación ante el INPSASEL.'),
  ('recomendacion_aptitud', 'cam_apto', null, 'CAM,REU,TRF', null, null, E'Apto para el nuevo perfil de riesgo del cargo.\nAntes de asumir el nuevo puesto debe recibir la notificación escrita de sus riesgos y la capacitación en los procedimientos de trabajo seguro.\nUsar el equipo de protección personal correspondiente al nuevo puesto.\nInformar al servicio médico cualquier síntoma relacionado con las nuevas tareas durante el periodo de adaptación.'),
  ('recomendacion_aptitud', 'no_apto_temporal', 'No apto temporal', 'PRE,PER,ANU,REI,EVE', 70, null, E'No apto de forma temporal para el cargo evaluado por los hallazgos descritos.\nNo realizar las tareas del cargo hasta recibir la nueva constancia de aptitud.\nDebe completar la evaluación y el tratamiento indicados por el especialista y consignar los informes en el servicio médico.\nUna vez controlada la condición, se realizará una nueva evaluación para definir la aptitud.'),
  ('recomendacion_aptitud', 'rin_apto', 'Reinserción laboral', 'RIN', 80, null, E'Apto para su reinserción laboral en las condiciones descritas.\nRealizar solo las tareas compatibles con su capacidad actual, según lo indicado en esta evaluación.\nSeguimiento médico ocupacional durante el periodo de reinserción, con la periodicidad indicada.\nReportar al servicio médico cualquier dificultad para realizar las tareas asignadas.'),
  ('recomendacion_aptitud', 'prn_control', 'Control prenatal', 'PRN', 81, null, E'Se evalúa a la trabajadora embarazada para verificar que las condiciones del puesto no comprometan su salud ni la del bebé.\nNo debe exponerse a sustancias químicas peligrosas, radiaciones, vibraciones, levantamiento de cargas pesadas ni jornadas nocturnas o prolongadas.\nCumplir sus controles prenatales y consignar los informes en el servicio médico.\nAcudir de inmediato al servicio médico ante sangrado, dolor, contracciones o cualquier signo de alarma.'),
  ('recomendacion_aptitud', 'psn_reintegro', 'Reintegro postnatal', 'PSN', 82, null, E'Culminado el periodo postnatal, se encuentra en condiciones de reincorporarse a sus labores.\nTiene derecho a los periodos de lactancia durante la jornada: coordinarlos con su supervisor.\nEvitar durante el periodo de lactancia la exposición a sustancias que puedan pasar a la leche materna.\nInformar al servicio médico cualquier molestia que limite sus tareas durante la reincorporación.'),
  ('recomendacion_aptitud', 'eve_apto', 'Evaluación especial', 'EVE', 83, null, E'Apto para la actividad o tarea especial evaluada (trabajo en altura, espacios confinados, manejo de vehículos u otra indicada).\nCumplir el permiso de trabajo, los procedimientos y el equipo de protección específicos de la tarea.\nSuspender la tarea y avisar al supervisor y al servicio médico si presenta mareo, malestar u otro síntoma durante su realización.\nRepetir la evaluación en la fecha indicada o al cambiar su condición de salud.'),
  ('recomendacion_empresa', 'emp_notificacion', null, null, null, 'prevencion', E'Notificar por escrito al trabajador, antes del inicio de labores o del cambio de puesto, los riesgos del puesto, sus efectos en la salud y las medidas de prevención (LOPCYMAT art. 56).\nConservar la notificación firmada en el expediente del trabajador y actualizarla cuando cambien las condiciones o el proceso de trabajo.'),
  ('recomendacion_empresa', 'emp_induccion', null, null, null, 'prevencion', E'Cumplir la inducción en seguridad y salud en el trabajo antes del inicio de labores: procedimientos de trabajo seguro, plan de emergencias y uso del equipo de protección personal.\nDejar constancia firmada de la inducción y programar la capacitación continua según el Programa de Seguridad y Salud en el Trabajo.'),
  ('recomendacion_empresa', 'emp_epp', null, null, null, 'prevencion', E'Dotar sin costo para el trabajador el equipo de protección personal según la matriz de riesgos del puesto, con su respectivo registro de entrega.\nSupervisar su uso correcto y reponerlo cuando se deteriore o venza.\nCapacitar al trabajador en el uso, cuidado y limitaciones de cada equipo.'),
  ('recomendacion_empresa', 'emp_pausas', null, null, null, 'prevencion', E'Implementar pausas activas de 5 a 10 minutos cada 2 horas en tareas repetitivas, de postura mantenida o frente a pantallas.\nRotar las tareas que exijan movimientos repetitivos y evaluar ergonómicamente el puesto de trabajo cuando haga falta.'),
  ('recomendacion_empresa', 'emp_cargas', null, null, null, 'columna', E'Evitar el levantamiento manual de cargas mayores a 23 kg por persona; usar ayudas mecánicas y trabajo en equipo.\nCapacitar en técnicas de levantamiento seguro y organizar las tareas para reducir los traslados y los giros del tronco con carga.'),
  ('recomendacion_empresa', 'emp_ruido', null, null, null, 'auditivo', E'Mantener el programa de conservación auditiva en los puestos con exposición a ruido: medición del ruido, control en la fuente y señalización de las áreas.\nDotar y supervisar el uso de protección auditiva y realizar audiometría anual a los trabajadores expuestos.'),
  ('recomendacion_empresa', 'emp_periodico', null, 'PRE,PER,ANU,POSV,REI', null, 'evaluacion', E'Programar la próxima evaluación médica periódica según la vigencia indicada en esta constancia.\nNotificar al servicio médico los cambios de puesto, reposos y reintegros para su evaluación oportuna.'),
  ('recomendacion_empresa', 'emp_restricciones', null, null, null, 'reposo', E'Respetar las limitaciones médicas indicadas durante su vigencia y comunicarlas por escrito al supervisor inmediato.\nNo asignar tareas que excedan dichas limitaciones y notificar al servicio médico cualquier cambio de puesto o de tareas.\nSolicitar la reevaluación médica al vencer la vigencia de las limitaciones.'),
  ('recomendacion_empresa', 'emp_reubicacion', null, null, null, 'reposo', E'Evaluar la reubicación temporal en un puesto compatible con las limitaciones señaladas, sin desmejora de sus condiciones laborales.\nDocumentar la reubicación y hacer seguimiento con el servicio médico y el Servicio de Seguridad y Salud en el Trabajo.'),
  ('recomendacion_empresa', 'emp_egreso', null, null, null, 'evaluacion', E'Archivar la constancia de egreso en el expediente del trabajador como evidencia de su estado de salud al salir.\nConservar la historia médica ocupacional por el tiempo que exige la normativa y entregar copia al trabajador si la solicita.'),
  ('recomendacion_empresa', 'emp_no_apto', 'Mientras no sea apto', 'PRE,PER,ANU,REI,EVE', 13, 'evaluacion', E'No asignar las tareas del cargo evaluado hasta contar con la nueva constancia de aptitud.\nFacilitar los permisos para las consultas y estudios indicados y notificar al servicio médico cuando el trabajador los consigne.'),
  ('recomendacion_empresa', 'emp_partes_blandas', 'Hernias y defectos de pared abdominal', '', 20, 'partes_blandas', E'Evitar asignar tareas con levantamiento o empuje de cargas pesadas, esfuerzos bruscos o maniobras de pujo repetidas.\nProveer ayudas mecánicas (carretillas, montacargas, polipastos) y organizar el trabajo en equipo para el manejo de cargas.\nFacilitar la evaluación y el tratamiento por cirugía y, tras una cirugía de pared, respetar el reposo y la reincorporación progresiva indicados.'),
  ('recomendacion_empresa', 'emp_columna', 'Columna: lumbalgia y hernia discal', '', 21, 'columna', E'Limitar el levantamiento manual de cargas, las posturas forzadas o mantenidas del tronco y la exposición a vibración de cuerpo entero.\nEvaluar ergonómicamente el puesto (altura del plano de trabajo, asiento, alcance) y aplicar los ajustes necesarios.\nImplementar pausas activas con estiramientos de columna y rotación de tareas.\nAnte lumbalgias a repetición, notificar al servicio médico para su estudio y para descartar origen ocupacional.'),
  ('recomendacion_empresa', 'emp_hombro', 'Hombro y miembro superior', '', 22, 'miembro_superior', E'Evitar tareas con los brazos por encima del nivel de los hombros, movimientos repetitivos de alta frecuencia y fuerza sostenida con las manos.\nRotar las tareas repetitivas, ajustar la altura de trabajo y proveer herramientas de agarre ergonómico y de bajo peso.\nImplementar pausas activas con estiramientos de hombro, codo, muñeca y mano.\nNotificar al servicio médico los casos de dolor persistente para su estudio y para descartar origen ocupacional.'),
  ('recomendacion_empresa', 'emp_hta', 'Hipertensión arterial', '', 23, 'cardiovascular', E'Facilitar el control de la tensión arterial en el servicio médico y los permisos para sus consultas de control.\nEvitar asignar, mientras no esté controlada, trabajos en altura, en espacios confinados, en calor extremo o la conducción de vehículos.\nPromover la alimentación con poca sal en el comedor y las pausas de descanso en jornadas prolongadas.'),
  ('recomendacion_empresa', 'emp_diabetes', 'Diabetes', '', 24, 'metabolico', E'Respetar los horarios de comida y de medicación del trabajador y permitirle llevar meriendas y controlar su glicemia.\nEvitar, mientras no esté controlada, trabajos en altura, con maquinaria peligrosa, en turnos nocturnos rotativos o la conducción de vehículos.\nDotar calzado de seguridad adecuado y vigilar las heridas en los pies, que cicatrizan con dificultad.'),
  ('recomendacion_empresa', 'emp_salud_mental', 'Ansiedad, depresión y estrés', '', 25, 'salud_mental', E'Revisar la carga de trabajo, los turnos y las metas del puesto, y evitar las jornadas prolongadas y el trabajo nocturno mientras dure el tratamiento.\nFacilitar los permisos para la atención por psicología o psiquiatría y respetar la confidencialidad del caso.\nEvaluar los factores de riesgo psicosocial del área y promover un clima laboral de apoyo, sin hostigamiento.\nEvitar asignar, durante la fase aguda, tareas de alto riesgo o el manejo de vehículos y maquinaria.'),
  ('recomendacion_empresa', 'emp_prenatal', 'Protección de la maternidad', 'PRN,PSN', 11, 'maternidad', E'Adecuar las tareas de la trabajadora embarazada o en lactancia: sin exposición a sustancias peligrosas, radiaciones, vibraciones ni levantamiento de cargas pesadas.\nGarantizar los permisos para sus controles prenatales, los periodos de lactancia y un espacio adecuado para ello.'),
  ('recomendacion_empresa', 'emp_accidente', 'Investigación del accidente', 'ACL', 12, 'reposo', E'Investigar el accidente (causas inmediatas y básicas) y declararlo ante el INPSASEL dentro de las 24 horas siguientes.\nAplicar las medidas correctivas con su responsable y fecha, e informar al Comité de Seguridad y Salud Laboral.'),
  ('recomendacion_paciente', 'pac_epp', null, null, null, 'prevencion', E'Usar en todo momento el equipo de protección personal asignado, mantenerlo limpio y en buen estado, y solicitar su reposición cuando se deteriore.\nCumplir los procedimientos de trabajo seguro y reportar al supervisor cualquier condición insegura.'),
  ('recomendacion_paciente', 'pac_higiene_postural', null, null, null, 'columna', E'Mantener higiene postural: espalda recta, flexionar las rodillas al levantar objetos y evitar giros del tronco con carga.\nAlternar posturas cada 30 a 60 minutos y realizar ejercicios de estiramiento durante las pausas.\nAcudir al servicio médico si presenta dolor de espalda, cuello o extremidades que persista más de 3 días.'),
  ('recomendacion_paciente', 'pac_hidratacion', null, null, null, 'habitos', E'Mantener una hidratación adecuada, de al menos 2 litros de agua al día, y aumentarla en ambientes calurosos o con esfuerzo físico.\nEvitar el exceso de bebidas azucaradas, gaseosas y energizantes.'),
  ('recomendacion_paciente', 'pac_dieta', null, null, null, 'habitos', E'Alimentación balanceada, baja en grasas, azúcares y sal, con frutas, verduras y fibra diariamente.\nRespetar los horarios de comida y evitar los alimentos procesados y las frituras.'),
  ('recomendacion_paciente', 'pac_ejercicio', null, null, null, 'habitos', E'Realizar actividad física regular de al menos 30 minutos, 5 días a la semana (caminar, trotar, nadar o bicicleta).\nComenzar de forma progresiva y consultar al médico antes de iniciar ejercicios intensos si tiene alguna enfermedad crónica.'),
  ('recomendacion_paciente', 'pac_ta', null, null, null, 'cardiovascular', E'Control periódico de la tensión arterial y consulta con medicina interna o cardiología.\nReducir el consumo de sal, mantener un peso adecuado y realizar actividad física regular.\nCumplir el tratamiento indicado sin suspenderlo por cuenta propia y acudir al servicio médico si presenta dolor de cabeza intenso, mareo o dolor en el pecho.'),
  ('recomendacion_paciente', 'pac_glicemia', null, null, null, 'metabolico', E'Control de glicemia en ayunas y evaluación por medicina interna o endocrinología.\nReducir el consumo de azúcares, harinas refinadas y bebidas azucaradas.\nMantener un peso adecuado y realizar actividad física regular; consignar los resultados de control en el servicio médico.'),
  ('recomendacion_paciente', 'pac_lipidos', null, null, null, 'metabolico', E'Control de colesterol y triglicéridos y evaluación por medicina interna.\nDieta baja en grasas saturadas, frituras y embutidos; aumentar el consumo de fibra, frutas y verduras.\nRealizar actividad física regular y repetir el perfil lipídico en el plazo indicado.'),
  ('recomendacion_paciente', 'pac_obesidad', null, null, null, 'metabolico', E'Plan de reducción de peso con orientación nutricional y actividad física regular.\nMeta inicial: reducir entre el 5 % y el 10 % del peso actual en 6 meses.\nControl de tensión arterial, glicemia y perfil lipídico, por su mayor riesgo cardiovascular.'),
  ('recomendacion_paciente', 'pac_tabaco', null, null, null, 'habitos', E'Abandonar el hábito tabáquico: es el principal factor de riesgo prevenible de enfermedad cardiovascular y respiratoria.\nPuede solicitar orientación en el servicio médico; evitar fumar en las áreas de trabajo, especialmente cerca de sustancias inflamables.'),
  ('recomendacion_paciente', 'pac_reposo', null, null, null, 'reposo', E'Cumplir el reposo y el tratamiento indicados, sin realizar actividades laborales durante el reposo.\nConsignar el reposo en el servicio médico lo antes posible y validarlo ante el IVSS cuando corresponda.\nAcudir a la evaluación de reintegro antes de reincorporarse a sus labores.'),
  ('recomendacion_paciente', 'pac_paraclinicos', null, null, null, 'evaluacion', E'Consignar en el servicio médico los resultados de los exámenes paraclínicos solicitados en el plazo indicado.\nRealizar los exámenes de sangre en ayunas de 8 a 12 horas, salvo indicación distinta.'),
  ('recomendacion_paciente', 'pac_control', null, null, null, 'evaluacion', E'Acudir a la consulta del especialista indicado en la referencia y traer su informe al servicio médico.\nCumplir el tratamiento y los estudios que indique el especialista y consignar los resultados para actualizar su historia médica ocupacional.'),
  ('recomendacion_paciente', 'pac_partes_blandas', 'Hernias y defectos de pared abdominal', '', 20, 'partes_blandas', E'No levantar ni empujar cargas pesadas, y evitar esfuerzos bruscos y el pujo prolongado.\nAcudir a la evaluación por cirugía general indicada y traer el informe al servicio médico.\nConsultar de inmediato si la hernia aumenta de tamaño, se pone dura, dolorosa o no regresa a su sitio (signos de complicación).'),
  ('recomendacion_paciente', 'pac_columna', 'Columna: lumbalgia y hernia discal', '', 21, 'columna', E'Levantar los objetos flexionando las rodillas, con la carga pegada al cuerpo y sin girar el tronco.\nRealizar a diario los ejercicios de fortalecimiento de abdomen y espalda y de estiramiento indicados por fisiatría.\nEvitar permanecer mucho tiempo sentado o de pie en la misma postura: cambiar de posición cada 30 a 60 minutos.\nConsultar de inmediato si el dolor se irradia a las piernas o hay hormigueo, pérdida de fuerza o alteración para orinar.'),
  ('recomendacion_paciente', 'pac_hombro', 'Hombro y miembro superior', '', 22, 'miembro_superior', E'Evitar elevar los brazos por encima de los hombros de forma repetida y los movimientos bruscos o de fuerza sostenida con las manos.\nRealizar los ejercicios de estiramiento y fortalecimiento indicados y aplicar frío local tras el esfuerzo si hay dolor.\nAcudir a la evaluación por traumatología o fisiatría indicada y consignar el informe en el servicio médico.'),
  ('recomendacion_paciente', 'pac_diabetes', 'Diabetes', '', 23, 'metabolico', E'Cumplir el tratamiento y el plan de alimentación indicados, sin saltar comidas, y llevar siempre una merienda.\nControlar la glicemia según lo indicado y la hemoglobina glicosilada cada 3 meses.\nRevisar a diario los pies, usar calzado cómodo y avisar de inmediato cualquier herida.\nAnte sudoración, temblor, mareo o confusión (glicemia baja), suspender la tarea, comer azúcar y avisar al supervisor.'),
  ('recomendacion_paciente', 'pac_salud_mental', 'Ansiedad, depresión y estrés', '', 24, 'salud_mental', E'Acudir a la evaluación y el control por psicología o psiquiatría indicados y cumplir el tratamiento sin suspenderlo por cuenta propia.\nMantener horarios regulares de sueño, actividad física y momentos de descanso y recreación.\nEvitar el consumo de alcohol, tabaco y otras sustancias.\nInformar al servicio médico si el estado de ánimo, el sueño o la concentración interfieren con su trabajo; la consulta es confidencial.'),
  ('recomendacion_paciente', 'pac_vacaciones', 'Durante las vacaciones', 'PREV,POSV', 14, 'evaluacion', E'Aprovechar el periodo vacacional para el descanso físico y mental; evitar trabajos o esfuerzos no habituales.\nSi presenta alguna enfermedad o lesión, acudir al médico y guardar el informe para presentarlo al regreso.'),
  ('recomendacion_paciente', 'pac_egreso', 'Al egreso', 'EGR', 15, 'evaluacion', E'Conservar copia de la constancia de egreso y de los exámenes realizados.\nMantener sus controles de salud con su médico de confianza o en la red pública de salud.'),
  ('recomendacion_paciente', 'pac_embarazo', 'Embarazo y lactancia', 'PRN,PSN', 16, 'maternidad', E'Cumplir los controles prenatales y el tratamiento indicado por su obstetra, y consignar los informes en el servicio médico.\nEvitar el levantamiento de cargas, las posturas forzadas y la exposición a sustancias peligrosas.\nAcudir de inmediato al médico ante sangrado, dolor abdominal, contracciones o disminución de los movimientos del bebé.'),
  ('recomendacion_paciente', 'pac_accidente', 'Después de un accidente', 'ACL,ACC', 17, 'reposo', E'Cumplir el tratamiento y las curas indicadas y vigilar signos de infección (enrojecimiento, calor, secreción o fiebre).\nReportar al servicio médico cualquier molestia persistente tras el accidente, aunque haya sido leve.');
