-- zamorApp Ocupacional · Recomendaciones más completas y clasificadas (pedidos de Cesar, 03 y 04-nov-2026)
-- 1) Los textos base de recomendaciones (aptitud, empresa y trabajador) pasan de una frase a varias líneas:
--    qué hacer, quién lo hace y cuándo volver. Cada línea sale numerada en el impreso. La aptitud (sale como
--    «Recomendaciones al trabajador» en la constancia) habla al trabajador; lo que hace la empresa va en su lista.
-- 2) Las copias de cada organización se actualizan SOLO si siguen iguales a su texto base: lo que el médico
--    editó en Configuración › Datos clínicos queda tal cual. Igual con el grupo (motivos).
-- 3) 23 recomendaciones nuevas: evaluaciones que no tenían (no apto temporal, reinserción, prenatal, postnatal,
--    evaluación especial) y por condición de salud (hernias y pared abdominal, columna, hombro y miembro superior,
--    hipertensión, diabetes, ansiedad y depresión, maternidad, accidente). Se copian a cada organización.
-- 4) Categoría (datos.categoria) para encontrarlas por botones desplegables en la consulta. Las que no la tienen
--    (p. ej. las traídas del SAME) se clasifican solas por su nombre (lib/recomendaciones-categorias.ts) y el médico
--    la cambia en Configuración. A las copias solo se les pone si no tienen una.
-- Los códigos no cambian: las plantillas de examen que ya los usan toman el texto nuevo solas.

create temp table _recomendaciones (lista text, codigo text, nombre text, grupo text, orden int, categoria text, texto text);

-- Copias sin editar (antes que la base, para comparar con el texto viejo)
update public.lista_items o
set texto = case when o.texto is not distinct from b.texto then r.texto else o.texto end,
    grupo = case when r.grupo is not null and o.grupo is not distinct from b.grupo then r.grupo else o.grupo end
from public.lista_items b
join _recomendaciones r on r.lista = b.lista and r.codigo = b.codigo
where b.org_id is null and o.base_id = b.id and o.org_id is not null
  and ((o.texto is not distinct from b.texto and o.texto is distinct from r.texto)
    or (r.grupo is not null and o.grupo is not distinct from b.grupo and o.grupo is distinct from r.grupo));

-- Categoría en las copias que aún no tienen
update public.lista_items o
set datos = coalesce(o.datos, '{}'::jsonb) || jsonb_build_object('categoria', r.categoria)
from public.lista_items b
join _recomendaciones r on r.lista = b.lista and r.codigo = b.codigo
where b.org_id is null and o.base_id = b.id and o.org_id is not null and r.categoria is not null
  and not (coalesce(o.datos, '{}'::jsonb) ? 'categoria');

-- Base
update public.lista_items b
set texto = r.texto, grupo = coalesce(r.grupo, b.grupo),
    datos = case when r.categoria is null then b.datos else coalesce(b.datos, '{}'::jsonb) || jsonb_build_object('categoria', r.categoria) end
from _recomendaciones r
where b.org_id is null and b.lista = r.lista and b.codigo = r.codigo
  and (b.texto is distinct from r.texto or b.grupo is distinct from coalesce(r.grupo, b.grupo)
    or (r.categoria is not null and b.datos->>'categoria' is distinct from r.categoria));

-- Nuevas en la base
select r.lista, r.codigo, r.nombre, r.grupo, r.texto, r.orden, case when r.categoria is null then '{}'::jsonb else jsonb_build_object('categoria', r.categoria) end
from _recomendaciones r
where r.nombre is not null
  and not exists (select 1 from public.lista_items b where b.org_id is null and b.lista = r.lista and b.codigo = r.codigo);

-- …y en cada organización (solo las que falten)
select public.copiar_listas_base(id) from public.organizaciones;

drop table _recomendaciones;
